-- 0076 — ROLLBACK, all or nothing. Generated by supabase/live/make_blocks_pack.sh — do not edit by hand.
-- Back to 0075. Removes no block. Roll back 0077 first if it is applied, and put the website back on direct
-- inserts first (the new website calls staff_block).
begin;
set local lock_timeout = '5s';
do $pre$ begin
  if not (true and (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '1e8dc62bedc9d9bbadcfd68cd906b71d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'staff_block') and (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '443366cc1f3829e0bc3991c238b5c90c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_block') and (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '58ae4fef2de6a7daaca5d9a48b639525' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'blocks_direct_write_rules') and (select coalesce(string_agg(policyname || ' (' || cmd || ')', ', ' order by policyname), 'none') from pg_policies where schemaname = 'public' and tablename = 'blocks') = 'blocks: staff read (SELECT), blocks: staff write (ALL)') then
    raise exception 'STOPPED, nothing changed: this database does not have the verified 0076 (or 0077 is still applied)';
  end if;
end $pre$;
create temp table blocks_before on commit drop as select (select count(*) || ' blocks, ' || coalesce(md5(string_agg(id::text || '|' || club_id || '|' || court_id || '|' || start_at || '|' || end_at || '|' || coalesce(reason, '') || '|' || created_by || '|' || created_at, ',' order by id)), '-') from public.blocks) as fp;
drop trigger if exists blocks_direct_write_rules on blocks;
drop function if exists blocks_direct_write_rules();
drop function if exists staff_block(uuid, uuid, timestamptz, timestamptz, text);
drop function if exists assert_valid_block(uuid, uuid, timestamptz, timestamptz);
do $post$ begin
  if (select fp from blocks_before) is distinct from (select count(*) || ' blocks, ' || coalesce(md5(string_agg(id::text || '|' || club_id || '|' || court_id || '|' || start_at || '|' || end_at || '|' || coalesce(reason, '') || '|' || created_by || '|' || created_at, ',' order by id)), '-') from public.blocks) then raise exception 'ROLLED BACK: saved blocks changed'; end if;
end $post$;
notify pgrst, 'reload schema';
commit;
select '0076 rolled back' as result;
